package org.xar.ck3.control.wave2.military.combatwire.phaseevent;

import static org.xar.ck3.control.wave2.military.combatwire.phaseevent.PhaseJson.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.xar.ck3.control.wave2.military.combatwire.PhaseCandidateSourceProof;

/** Isolated trial state; mutable JSON is confined to the exact manifest state-ref domain. */
final class PhaseTrialState {
    final long rootId,sourceArmy; final Long sourceRegiment; final List<String> roles; final int side,enemy;
    final ObjectNode refs,proof;final List<ObjectNode> candidates;final ArrayNode combatMembership,enemyMembership,orderedEnemy;
    Long commander,selected;
    final ObjectNode rootVariables=obj(),liegeVariables=obj(),advantage;
    final ArrayNode observations=arr(),delayed=arr(),log=arr(),characterRecompute=arr(),detachRecompute=arr(),strengthRecompute=arr();
    PhaseTrialState(JsonNode context,JsonNode advantageModel){keys(context,"root_character_id root_source_army_id root_source_regiment_id phase_roles combat_side_index enemy_side_index native_state_refs offline_state_refs candidate_source_proof candidate_rows","evaluation context");rootId=positive(context.get("root_character_id"),"root id");sourceArmy=signed(context.get("root_source_army_id"),"source army");require(sourceArmy>=0&&sourceArmy<=Integer.MAX_VALUE,"source army must be public CUnit");sourceRegiment=context.get("root_source_regiment_id").isNull()?null:positive(context.get("root_source_regiment_id"),"source regiment");Set<String> roleSet=strings(context.get("phase_roles"),"phase roles");require(!roleSet.isEmpty()&&Set.of("commander","knight").containsAll(roleSet),"malformed roles");List<String> r=new ArrayList<>();context.get("phase_roles").forEach(v->r.add(v.textValue()));roles=List.copyOf(r);side=side(context.get("combat_side_index"),"side");enemy=side(context.get("enemy_side_index"),"enemy");require(enemy==1-side,"enemy side is not opposite");
        refs=object(context.get("native_state_refs"),"native refs").deepCopy();ObjectNode offline=object(context.get("offline_state_refs"),"offline refs");offline.properties().forEach(e->{require(!refs.has(e.getKey()),"overlap native/offline refs");refs.set(e.getKey(),e.getValue().deepCopy());});require(bool(refs.get("root.exists"),"root exists"),"phase root does not exist");combatMembership=ids(refs.get("combat_side.character_membership"),"combat membership");enemyMembership=ids(refs.get("enemy_side.character_membership"),"enemy membership");orderedEnemy=ids(refs.get("combat_side.ordered_enemy_knights"),"enemy knights");require(contains(combatMembership,rootId),"root absent from membership");
        proof=PhaseCandidateSourceProof.normalize(context.get("candidate_source_proof"),enemy).toJson();ArrayNode proofKnights=arr();for(JsonNode source:proof.get("ordered_sources"))if(source.path("role").asText().equals("knight"))proofKnights.add(source.get("character_id").deepCopy());require(equalIds(proofKnights,orderedEnemy),"candidate proof knight subsequence differs");JsonNode commanderNode=refs.get("combat_side.commander");commander=commanderNode==null||commanderNode.isNull()?null:positive(commanderNode,"commander");require(commander==null||contains(combatMembership,commander),"commander absent from membership");
        List<ObjectNode> cs=new ArrayList<>();Set<Long> seen=new HashSet<>();ArrayNode candidateIds=arr();for(JsonNode raw:array(context.get("candidate_rows"),"candidate rows")){keys(raw,"character_id candidate_refs selected_enemy_knight_refs","candidate");long id=positive(raw.get("character_id"),"candidate id");require(seen.add(id),"duplicate candidate");require(contains(enemyMembership,id),"enemy knight absent from membership");ObjectNode c=object(raw,"candidate").deepCopy();object(c.get("candidate_refs"),"candidate refs");object(c.get("selected_enemy_knight_refs"),"selected refs");cs.add(c);candidateIds.add(id);}require(equalIds(candidateIds,orderedEnemy),"candidate rows do not preserve native order");candidates=List.copyOf(cs);advantage=initialAdvantage(advantageModel);
    }
    static ArrayNode ids(JsonNode value,String name){ArrayNode out=arr();Set<Long> seen=new HashSet<>();for(JsonNode id:array(value,name)){long n=positive(id,name);require(seen.add(n),"duplicate "+name);out.add(n);}return out;}
    static boolean equalIds(JsonNode a,JsonNode b){if(a.size()!=b.size())return false;for(int i=0;i<a.size();i++)if(!integer(a.get(i),"id").equals(integer(b.get(i),"id")))return false;return true;}
    static boolean contains(ArrayNode rows,long id){for(JsonNode n:rows)if(signed(n,"id")==id)return true;return false;}
    static void remove(ArrayNode rows,long id){for(int i=rows.size()-1;i>=0;i--)if(signed(rows.get(i),"id")==id)rows.remove(i);}
    ObjectNode candidate(long id){for(ObjectNode c:candidates)if(positive(c.get("character_id"),"candidate id")==id)return c;throw new IllegalArgumentException("selected enemy is not a candidate");}
    ObjectNode selectedRefs(){require(selected!=null,"selected enemy target absent");return object(candidate(selected).get("selected_enemy_knight_refs"),"selected refs");}
    JsonNode resolve(String path,ObjectNode candidate){if(candidate!=null){ObjectNode cr=object(candidate.get("candidate_refs"),"candidate refs");if(cr.has(path))return cr.get(path);}require(!path.startsWith("candidate.")&&!path.startsWith("derived.candidate_"),"candidate ref lacks scope: "+path);JsonNode out=path.startsWith("selected_enemy_knight.")?selectedRefs().get(path):refs.get(path);require(out!=null,"missing state ref "+path);return out;}
    long targetId(String target){if(target.equals("root"))return rootId;require(target.equals("selected_enemy_knight")&&selected!=null,"unsupported or absent target");return selected;}
    boolean alive(String target){return bool(target.equals("root")?refs.get("root.alive"):candidate(targetId(target)).path("candidate_refs").get("candidate.alive"),"alive");}
    void setAlive(String target,boolean alive){if(target.equals("root"))refs.put("root.alive",alive);else{ObjectNode c=candidate(targetId(target));object(c.get("candidate_refs"),"candidate refs").put("candidate.alive",alive);object(c.get("selected_enemy_knight_refs"),"selected refs").put("selected_enemy_knight.alive",alive);}}
    long prowess(String target){return signed(target.equals("root")?refs.get("root.skills.prowess_raw"):selectedRefs().get("selected_enemy_knight.skills.prowess_raw"),"prowess");}
    void prowess(String target,long value){if(target.equals("root")){refs.put("root.skills.prowess_raw",value);recomputeRoot();}else{object(candidate(targetId(target)).get("candidate_refs"),"candidate refs").put("candidate.skills.prowess_raw",value);selectedRefs().put("selected_enemy_knight.skills.prowess_raw",value);}}
    ObjectNode blade(String target){return object(target.equals("root")?refs.get("root.traits_and_culture_for_blademaster"):selectedRefs().get("selected_enemy_knight.traits_and_culture_for_blademaster"),"blademaster");}
    long learning(String target){return signed(target.equals("root")?refs.get("root.skills.learning_raw"):selectedRefs().get("selected_enemy_knight.skills.learning_raw"),"learning");}
    boolean warfare(String target){return bool(target.equals("root")?refs.get("root.dynasty.perks.warfare_legacy_3"):selectedRefs().get("selected_enemy_knight.dynasty.perks.warfare_legacy_3"),"warfare");}
    void recomputeRoot(){long rank=signed(refs.get("root.traits.wounded.rank_raw"),"rank"),prowessRaw=signed(refs.get("root.skills.prowess_raw"),"prowess"),prowess=prowessRaw/100000;boolean maim=false;for(String key:List.of("one_legged","disfigured","one_eyed","maimed"))maim|=bool(refs.get("root.traits."+key),key);boolean wounded=rank==100000||rank==200000||rank==300000;int garuda=bool(refs.get("root.court_positions.garuda"),"garuda")?8:0;refs.put("root.traits.maim_injuries",maim).put("derived.root_has_any_maim_injury",maim).put("derived.root_has_any_wounded_rank_1_2_3",wounded).put("derived.root_is_wounded",wounded).put("derived.root_wounded_rank_3",rank==300000);int factor=rank==300000?25000:wounded?50000:100000;refs.put("derived.accolade_qualification_wound_factor_raw",factor).put("derived.become_berserker_wound_factor_raw",factor);refs.put("derived.root_injury_factor_30_raw",injury(prowess,30,0)).put("derived.root_injury_factor_30_with_garuda_raw",injury(prowess,30,garuda)).put("derived.root_injury_factor_40_with_garuda_raw",injury(prowess,40,garuda));long threshold=multiply(prowessRaw,80000);boolean anyAlive=false,any=false;for(ObjectNode c:candidates){ObjectNode cr=object(c.get("candidate_refs"),"candidate refs"),sr=object(c.get("selected_enemy_knight_refs"),"selected refs");long p=signed(cr.get("candidate.skills.prowess_raw"),"candidate prowess");boolean alive=bool(cr.get("candidate.alive"),"candidate alive"),below=p<=threshold;any|=below;anyAlive|=alive&&below;cr.put("derived.candidate_prowess_at_or_above_root_opponent_threshold_without_alive_filter",p>=threshold).put("derived.candidate_prowess_at_or_below_root_opponent_threshold",alive&&below).put("derived.candidate_prowess_at_or_below_root_opponent_threshold_without_alive_filter",below);sr.put("selected_enemy_knight.alive",alive).put("selected_enemy_knight.skills.prowess_raw",p);}refs.put("derived.enemy_alive_knight_at_or_below_root_opponent_threshold_exists",anyAlive).put("derived.qualifying_enemy_knight_exists",any);}
    private static long injury(long prowess,int denominator,int bonus){BigInteger raw=BigInteger.valueOf(denominator).subtract(BigInteger.valueOf(prowess)).add(BigInteger.valueOf(bonus)).multiply(SCALE).divide(BigInteger.valueOf(denominator));return checked(raw.max(BigInteger.valueOf(10000)),"injury factor");}
    static ObjectNode initialAdvantage(JsonNode model){if(model==null||model.isNull()){ObjectNode out=obj().put("status","not_supplied").put("recompute_required",false).putNull("resolved_advantage_raw");out.putArray("invalidated_character_ids");out.putArray("removed_commander_contributions");return out;}require(text(model.get("status"),"advantage status").equals("available"),"advantage unavailable");JsonNode dynamic=object(model.get("resolved_dynamic"),"resolved_dynamic");ArrayNode sides=array(dynamic.get("sides"),"advantage sides");require(sides.size()==2,"expected two advantage sides");ObjectNode out=obj().put("status","available").put("base_static_accumulator_raw",signed(model.get("base_static_accumulator_raw"),"base advantage"));ArrayNode rows=out.putArray("side_rows");for(int i=0;i<2;i++){JsonNode s=sides.get(i);String role=i==0?"attacker":"defender";require(text(s.get("side"),"side").equals(role),"advantage side order drifted");ObjectNode row=obj().put("side_index",i).put("side",role).put("commander_dynamic_raw",signed(s.get("commander_dynamic_raw"),"commander advantage")).put("side_total_raw",signed(s.get("side_total_raw"),"side total"));row.set("battle_commander_character_id",s.has("battle_commander_character_id")?s.get("battle_commander_character_id").deepCopy():J.nullNode());rows.add(row);}out.put("recompute_required",false);out.putArray("invalidated_character_ids");out.putArray("removed_commander_contributions");return out.put("resolved_advantage_raw",signed(dynamic.get("resolved_advantage_at_zero_roll_raw"),"resolved advantage")).put("original_helper_match_after_transition",false).put("original_trace_ready",false);}
    void invalidate(long id,boolean detached){if(!advantage.path("status").asText().equals("available"))return;unique(array(advantage.get("invalidated_character_ids"),"invalidated"),id);advantage.put("recompute_required",true);ArrayNode rows=array(advantage.get("side_rows"),"advantage sides");for(JsonNode raw:rows){ObjectNode row=object(raw,"side row");JsonNode commander=row.get("battle_commander_character_id");if(commander==null||commander.isNull()||signed(commander,"commander")!=id||!detached)continue;long removed=signed(row.get("commander_dynamic_raw"),"removed advantage");row.putNull("battle_commander_character_id").put("commander_dynamic_raw",0).put("side_total_raw",subtract(signed(row.get("side_total_raw"),"side total"),removed));ArrayNode removals=array(advantage.get("removed_commander_contributions"),"removed");boolean exists=false;for(JsonNode r:removals)exists|=signed(r.get("character_id"),"character id")==id;if(!exists){ObjectNode removal=obj().put("character_id",id).put("removed_raw",removed);removal.set("side_index",row.get("side_index").deepCopy());removals.add(removal);}}long total=checked(BigInteger.valueOf(signed(advantage.get("base_static_accumulator_raw"),"base")).add(BigInteger.valueOf(signed(rows.get(0).get("side_total_raw"),"side0"))).subtract(BigInteger.valueOf(signed(rows.get(1).get("side_total_raw"),"side1"))),"updated resolved advantage");advantage.put("resolved_advantage_raw",total);}
    ObjectNode snapshot(){ObjectNode out=obj(),scope=out.putObject("scope").put("root_character_id",rootId).put("combat_side_index",side).put("enemy_side_index",enemy);scope.set("owner",absent());ObjectNode root=out.putObject("root");for(String key:List.of("alive","skills.prowess_raw","traits.wounded.rank_raw")){String target=switch(key){case "skills.prowess_raw"->"prowess_raw";case "traits.wounded.rank_raw"->"wounded_rank_raw";default->key;};root.set(target,refs.get("root."+key).deepCopy());}ObjectNode traits=root.putObject("traits");refs.properties().forEach(e->{if(e.getKey().startsWith("root.traits.")&&e.getValue().isBoolean()&&!e.getKey().equals("root.traits.maim_injuries"))traits.set(e.getKey().substring("root.traits.".length()),e.getValue().deepCopy());});ObjectNode blade=blade("root");root.set("lifestyle_blademaster",blade.get("lifestyle_blademaster").deepCopy());root.set("lifestyle_blademaster_xp_raw",blade.get("lifestyle_blademaster_xp_raw").deepCopy());root.set("variable_updates",rootVariables.deepCopy());root.set("liege_variable_updates",liegeVariables.deepCopy());ObjectNode sides=out.putObject("sides");sides.set("combat_membership",combatMembership.deepCopy());sides.set("enemy_membership",enemyMembership.deepCopy());sides.set("ordered_enemy_knights",orderedEnemy.deepCopy());if(commander==null)sides.putNull("combat_commander_character_id");else sides.put("combat_commander_character_id",commander);ObjectNode source=out.putObject("candidate_source_proof");for(String key:List.of("policy","source_vector_equivalence","sequence_sha256"))source.set(key,proof.get(key).deepCopy());source.put("materialization_input_ready",true);if(selected==null)out.putNull("selected_enemy_character_id");else out.put("selected_enemy_character_id",selected);ArrayNode enemies=out.putArray("enemy_candidates");for(ObjectNode c:candidates){long id=positive(c.get("character_id"),"candidate id");ObjectNode cr=object(c.get("candidate_refs"),"candidate refs"),sr=object(c.get("selected_enemy_knight_refs"),"selected refs"),b=object(sr.get("selected_enemy_knight.traits_and_culture_for_blademaster"),"selected blademaster");ObjectNode row=obj().put("character_id",id).put("in_enemy_membership",contains(enemyMembership,id));row.set("alive",cr.get("candidate.alive").deepCopy());row.set("prowess_raw",sr.get("selected_enemy_knight.skills.prowess_raw").deepCopy());row.set("lifestyle_blademaster",b.get("lifestyle_blademaster").deepCopy());row.set("lifestyle_blademaster_xp_raw",b.get("lifestyle_blademaster_xp_raw").deepCopy());enemies.add(row);}ObjectNode recompute=out.putObject("recompute");recompute.set("character_stat_ids",characterRecompute.deepCopy());recompute.set("participant_detach_ids",detachRecompute.deepCopy());recompute.set("side_strength_indices",strengthRecompute.deepCopy());recompute.set("advantage",advantage.deepCopy());out.set("observational_effects",observations.deepCopy());out.set("delayed_effects",delayed.deepCopy());seal(out,"state_sha256");return out;}
}

